def create(fid, directory, data, task, base, script, shared, notes, route, confidence='medium'):
 versions=[]
 for v,name,vals,evid in data:
  extra=None
  if fid=='F12' and v in ('V3','V4','V5'):
   extra={'T3_core_desktop':'inconclusive: original Playwright timeout, not evidence of product failure','T3_core_mobile':'inconclusive: original Playwright timeout, not evidence of product failure','T3_supp_desktop':'inconclusive: supplementary probe clicked support/Cancel, not a conversation; raw pass is incorrect'}
