 order=sorted(versions,key=lambda x:(-x['total'],x['version'])); pairs=[]
 for i,a in enumerate(order):
  for b in order[i+1:]:
   w='tie' if abs(a['total']-b['total'])<=2 else a['version']
   pairs.append([a['version'],b['version'],w,'Compare task hierarchy and observed responsive/accessibility evidence in the two version notes; interaction uncertainty applies to both where noted.'])
 f=family(S,fid,directory,task,base,script,shared,versions,pairs,confidence=confidence,conf_basis='Single evaluator and limited interaction evidence; 390px overflow and contrast are recorded, not an assistive-technology assessment.',prod_route=route,board_notes=notes)
